      'jr.gateB': "Следующие главы пересказывают кампанию до самого конца: индустрию, нефть, финал. Если ты ещё проходишь сборку — лучше вернуться сюда позже.",
      'jr.gateBtn': "Всё равно открыть",
      'jr.note': "<b>Записи взяты из самой сборки.</b> Это описания квестов, помеченные в книге как «Из записей выжившего» — авторский текст, перенесённый без правок. Поэтому журнал существует только на русском: английской версии этих строк в сборке нет.",
