      'jr.notePart': "<b>Записи взяты из самой сборки.</b> Переведено {n} из {m} — остальные показаны на русском, как их написал автор.",
      'jr.noteFull': "<b>Записи взяты из самой сборки.</b> Это описания квестов, помеченные в книге как «Из записей выжившего». Перевод неофициальный.",
