      'cdx.findPath': "Показать путь до «{n}» →",
      'intro.kicker': "// Системный запуск",
      'intro.title': "Вход в узел Astral",
      'intro.text': "Мир замёрз. Реакторы остыли. То, что осталось — двигается в снегу. Добро пожаловать в атмосферный портал сборки: диагностика, радиоэфир и скрытые протоколы доступны. Тройной клик по логотипу откроет секретный канал.",
      'intro.lMode': "Режим",
