      'intro.start': "Запустить узел",
      'intro.skip': "Пропустить интро",
      'dl.badge': "// ПРОТОКОЛ РАЗВЁРТЫВАНИЯ {v}",
      'dl.ctaTitle': "Готов войти в <span class=\"hl\">мёртвый мир?</span>",
      'dl.ctaText': "Отдельная страница проведёт тебя через установку шаг за шагом: системные требования, выбор лаунчера, загрузка, настройка памяти и шейдеров. Ничего не сломается с первого раза.",
      'dl.lVersion': "Версия",
      'dl.lSize': "Размер",
      'dl.lMods': "Модов",
      'dl.lInstall': "Установка",
      'dl.vSteps': "5 шагов",
      'dl.vSize': "437 МБ",
      'cdx.title': "Что делать <span>дальше</span>",
      'cdx.lead': "Порядок, в котором сборка открывается: что за чем идёт и что чем заблокировано. Отмечай пройденное — узел запомнит, где ты остановился. Shift + клик по карточке покажет путь до неё.",
      'cdx.clicks': "<b>Клик</b> — отметить пройденное. <b>Shift + клик</b> — подсветить путь до узла. <b>Alt + клик</b> — построить маршрут: что осталось сделать до этой цели.",
