      'cdx.notice': "<b>Ранняя игра пока описана не полностью.</b> Узлы с пометкой «не подтверждено» ждут сверки по файлам сборки — квестбуку и рецептам. Мы не выдумываем рецепты: лучше пробел, чем неверная подсказка.",
