      'f.kicker': '// Что внутри', 'f.title': 'Ключевые особенности',
      'f.sub': '{n} столпов, на которых держится приключение в Astral RPG.',
      'feat.winter.t': "Вечная зима", 'feat.winter.d': "Температура тела, обморожение и гипотермия. Холод во всех биомах убивает быстрее зомби. Нужны костры, утеплённая одежда и тепло — иначе смерть от мороза за минуты.",
      'feat.infected.t': "Усиленные заражённые", 'feat.infected.d': "Десятки типов: быстрые бегуны, бронированные, взрывные, ночные охотники. Орды (The Hordes) накатывают волнами по ночам. Укус заражает — без лекарства инфекция прогрессирует.",
      'feat.guns.t': "Реалистичный огнестрел", 'feat.guns.d': "TACZ и 4 пака оружия: отдача, перезарядка, прицелы, обвесы, заклинивание. От пистолетов до штурмовых винтовок — патроны на вес золота, каждый выстрел на счету.",
      'feat.create.t': "Глубокая техника Create", 'feat.create.d': "30+ аддонов Create: конвейеры, поезда, генераторы, автоматическое производство патронов, большие пушки для обороны и даже ядерная энергия для поздней игры.",
      'feat.medicine.t': "Медицина по частям тела", 'feat.medicine.d': "First Aid: урон по конечностям, переломы, кровотечения, шины и бинты. Cure: система заражения с лечением. Здоровье — это не одна полоска, а состояние каждой части тела.",
      'feat.food.t': "Порча и голод", 'feat.food.d': "Еда гниёт без консервации (Diet/Spoiled). Однообразный рацион насыщает хуже — нужно разнообразие. Питание превращается в тактическую задачу долгого выживания.",
      'feat.defense.t': "Оборона базы", 'feat.defense.d': "SecurityCraft: камеры, кодовые замки, мины, сигнализации, лазеры. Illager Invasion: враждебные NPC штурмуют убежище. База — это крепость, которую нужно защищать.",
      'feat.world.t': "Мёртвый мир", 'feat.world.d': "Tectonic генерирует ледяные пики и тундру. Заброшенные города, бункеры, военные базы, баррикады. Immersive Weathering состарил мир — всё выглядит давно покинутым.",
      'feat.shaders.t': "Эксклюзивные шейдеры", 'feat.shaders.d': "Кастомный пресет на базе Complementary + EuphoriaPatches: холодная цветокоррекция, объёмный туман, светящийся снег. 5 профилей — от Potato до Extreme под любое железо.",
      'mods.kicker': '// Каталог пакета', 'mods.title': 'Список модов',
