      'dlp.guidePrism': ['Скачай и установи <b>Prism Launcher</b> с prismlauncher.org','Нажми <code>Add Instance</code> → вкладка <code>Import</code>','Выбери <code>Import from zip</code> и укажи архив <b>Prism / MultiMC</b> — тот, что со второй кнопки на шаге 3, а не универсальный','Дождись распаковки → выбери инстанс → <code>Edit</code> → <code>Settings → Java</code> и выбери <b>Java 17</b>','Нажми <code>Launch</code> — готово!'],
      'dlp.guideCurse': ['Открой приложение <b>CurseForge</b> → раздел Minecraft','Нажми <code>Create Custom Profile</code> → <code>Import</code>','Укажи скачанный архив сборки (.zip)','После импорта: <code>⋮ → Profile Options → Java Settings</code>, выдели память','Нажми <code>Play</code>'],
      'dlp.guideAt': ['Установи <b>ATLauncher</b> с atlauncher.com','Вкладка <code>Packs</code> → <code>Add Pack</code> → <code>Import</code>','Выбери архив сборки','Settings → Java/Minecraft → выдели память и выбери Java 17','Запусти инстанс кнопкой <code>Play</code>'],
      'dlp.s3t': 'Загрузка архива', 'dlp.s3tag': '// получение сборки',
      'dlp.s3lead': "Два архива под разные способы установки. Универсальный — для ручной установки и любого лаунчера. Отдельный — готовый инстанс для Prism и MultiMC, импортируется одним действием. CurseForge — официальная страница со статистикой.",
