      'rl.title': "How things work here",
      'rl.lead': "The Aether rests on a few simple agreements. There are not many, and they are not about formalities — they are about making this a place worth coming back to.",
      'rl.h1': "Rules of the Aether",
      'rl.h2': "What the station keeps about you",
      'rl.h3': "Age and responsibility",
      'rl.r1': "<b>Respect other survivors.</b> Insults, pile-ons and threats lead straight to a mute. Argue about shaders all you like; do not go after the person.",
      'rl.r2': "<b>No ads, no spam.</b> Links to your own projects belong in answers to questions, not in every message.",
      'rl.r3': "<b>Do not post other people's data.</b> Real names, addresses, private chats, screenshots of DMs — not here.",
      'rl.r4': "<b>Keep it age-appropriate.</b> Teenagers read the Aether: no porn, no cruelty for its own sake, no drug promotion.",
      'rl.r5': "<b>Link to pages, not files.</b> Direct links to archives and executables are removed: the station cannot check what is inside them.",
      'rl.r6': "<b>One voice, one survivor.</b> Vote farming, second accounts for upvotes and impersonating someone's callsign are stopped.",
      'rl.r7': "<b>Report instead of fighting.</b> The report button under a message works and reaches a keeper. A shouting match does not.",
