      'f.kicker': '// What\u2019s inside', 'f.title': 'Key Features',
      'f.sub': '{n} pillars that the journey in Astral RPG stands on.',
      'feat.winter.t': "Endless winter", 'feat.winter.d': "Body temperature, frostbite and hypothermia. The cold kills faster than zombies in every biome. You need fires, insulated clothing and warmth — otherwise you freeze to death in minutes.",
      'feat.infected.t': "Enhanced infected", 'feat.infected.d': "Dozens of types: fast runners, armoured, explosive, night hunters. The Hordes roll in waves after dark. A bite infects you — without medicine the infection keeps progressing.",
      'feat.guns.t': "Realistic firearms", 'feat.guns.d': "TACZ plus four weapon packs: recoil, reloading, sights, attachments, jamming. From pistols to assault rifles — ammunition is worth its weight in gold and every shot counts.",
      'feat.create.t': "Deep Create tech", 'feat.create.d': "30+ Create addons: conveyors, trains, generators, automated ammunition production, big cannons for defence and even nuclear power for the late game.",
      'feat.medicine.t': "Limb-based medicine", 'feat.medicine.d': "First Aid: limb damage, fractures, bleeding, splints and bandages. Cure: an infection system with treatment. Health is not one bar but the condition of every body part.",
      'feat.food.t': "Spoilage and hunger", 'feat.food.d': "Food rots without preservation (Diet/Spoiled). A monotonous diet feeds you worse — you need variety. Eating turns into a tactical problem of long-term survival.",
      'feat.defense.t': "Base defence", 'feat.defense.d': "SecurityCraft: cameras, keypad locks, mines, alarms, lasers. Illager Invasion: hostile NPCs storm your shelter. A base is a fortress you have to hold.",
      'feat.world.t': "A dead world", 'feat.world.d': "Tectonic generates ice spikes and tundra. Abandoned cities, bunkers, military bases, barricades. Immersive Weathering has aged the world — everything looks long deserted.",
      'feat.shaders.t': "Exclusive shaders", 'feat.shaders.d': "A custom preset built on Complementary + EuphoriaPatches: cold colour grading, volumetric fog, glowing snow. Five profiles from Potato to Extreme for any hardware.",
      'mods.kicker': '// Pack catalogue', 'mods.title': 'Mod List',
      'mods.sub': '197 mods, hand-picked and tested. Find one or filter by category.',
      'mods.search': 'Search a mod\u2026',
      'cat.all': 'All', 'cat.survival': 'Survival', 'cat.atmosphere': 'Atmosphere',
      'cat.tech': 'Tech', 'cat.world': 'World', 'cat.perf': 'Performance',
