      'rl.kicker': "// Статут вузла · станція Буран",
      'rl.title': "Як тут заведено",
      'rl.lead': "Ефір тримається на кількох простих домовленостях. Їх небагато, і вони не про формальності — а про те, щоб сюди хотілося повертатися.",
      'rl.h1': "Правила ефіру",
      'rl.h2': "Що станція про тебе зберігає",
      'rl.h3': "Вік і відповідальність",
      'rl.r1': "<b>Поважай вцілілих.</b> Образи, цькування та погрози — прямий шлях до заглушення. Сперечатися про шейдери можна, переходити на людину — ні.",
      'rl.r2': "<b>Жодної реклами і спаму.</b> Посилання на свої проєкти доречні у відповідь на питання, а не в кожному повідомленні.",
      'rl.r3': "<b>Не викладай чужі дані.</b> Справжні імена, адреси, листування, скриншоти особистих повідомлень — не сюди.",
      'rl.r4': "<b>Тримай віковий поріг.</b> Ефір читають підлітки: без порнографії, жорстокості заради жорстокості та пропаганди наркотиків.",
      'rl.r5': "<b>Посилання — на сторінки, а не на файли.</b> Прямі посилання на архіви та виконувані файли видаляються: перевірити їхній вміст станція не може.",
      'rl.r6': "<b>Один голос — один вцілілий.</b> Накрутка голосів, другі акаунти заради апвоутів і підробка чужого позивного припиняються.",
      'rl.r7': "<b>Скаржся, а не воюй.</b> Кнопка «поскаржитися» під повідомленням працює й доходить до наглядача. Взаємна лайка — ні.",
      'rl.d1a': "Позивний, статус, клас, фракція",
