      'rl.d1c': "Щоб тебе впізнавали в ефірі та в особовій справі",
      'rl.d2a': "Анонімний номер (uid)",
      'rl.d2b': "База вузла",
      'rl.d2c': "Відрізняє одного вцілілого від іншого. Імені й пошти в ньому немає",
      'rl.d3a': "Повідомлення, ідеї, креслення, записи про загибель",
