      'rl.d6a': "Лічильники переглядів і завантажень",
      'rl.d6b': "База вузла",
      'rl.d6c': "Загальні числа без прив'язки до людей — просто «скільки всього»",
      'rl.a1': "Ефір — відкритий чат. Усе, що ти пишеш, видно будь-кому, хто зайде на вузол, включно з пошуковими системами.",
      'rl.a2': "Якщо тобі менше 14 років, пиши сюди лише з відома батьків.",
      'rl.a3': "Збірка і сайт — аматорський проєкт однієї людини. Він робиться вечорами і може бути недоступним без попередження.",
      'rl.rNote': "Наглядач може видалити повідомлення та заглушити вцілілого на добу. Усі такі дії потрапляють до журналу, відкритого для читання будь-кому.",
      'rl.dLead': "Коротко: лише те, що потрібно ефіру для роботи. Ні реклами, ні аналітики, ні продажу даних — тут просто немає ні того, ні іншого.",
