      'rl.kicker': "// Satzung des Knotens · Station Buran",
      'rl.title': "Wie es hier zugeht",
      'rl.lead': "Der Äther beruht auf wenigen einfachen Absprachen. Es sind nicht viele, und es geht nicht um Formalitäten — sondern darum, dass man gern wiederkommt.",
      'rl.h1': "Regeln des Äthers",
      'rl.h2': "Was die Station über dich speichert",
      'rl.h3': "Alter und Verantwortung",
      'rl.r1': "<b>Respektiere die anderen Überlebenden.</b> Beleidigungen, Hetze und Drohungen führen direkt zur Stummschaltung. Über Shader streiten ist erlaubt, persönlich werden nicht.",
      'rl.r2': "<b>Keine Werbung, kein Spam.</b> Links auf eigene Projekte gehören in Antworten auf Fragen, nicht in jede Nachricht.",
      'rl.r3': "<b>Keine fremden Daten.</b> Echte Namen, Adressen, private Chats, Screenshots von DMs — nicht hier.",
      'rl.r4': "<b>Bleib jugendfrei.</b> Im Äther lesen Jugendliche mit: keine Pornografie, keine Grausamkeit um ihrer selbst willen, keine Drogenwerbung.",
      'rl.r5': "<b>Links auf Seiten, nicht auf Dateien.</b> Direkte Links auf Archive und ausführbare Dateien werden entfernt: die Station kann ihren Inhalt nicht prüfen.",
      'rl.r6': "<b>Eine Stimme, ein Überlebender.</b> Gekaufte Stimmen, Zweitkonten für Upvotes und das Fälschen fremder Rufzeichen werden unterbunden.",
      'rl.r7': "<b>Melde, statt zu kämpfen.</b> Der Melde-Knopf unter einer Nachricht funktioniert und erreicht die Aufsicht. Ein Schlagabtausch nicht.",
      'rl.d1a': "Rufzeichen, Status, Klasse, Fraktion",
