      'rl.d2c': "Unterscheidet einen Überlebenden vom anderen. Kein Name, keine E-Mail darin",
      'rl.d3a': "Nachrichten, Ideen, Baupläne, Todeseinträge",
      'rl.d3b': "Knoten-Datenbank, offen lesbar",
      'rl.d3c': "Das ist der Äther — alles Geschriebene sehen alle",
      'rl.d4a': "Überlebenstag und Rekord",
      'rl.d4b': "Knoten-Datenbank + dein Browser",
      'rl.d4c': "Der Rang auf dem Ausweis und eine Zeile in der Akte",
      'rl.d5a': "Ausgeblendete Überlebende, Signaleinstellungen, Codex-Fortschritt",
      'rl.d5b': "Nur dein Browser",
      'rl.d5c': "Das gehört dem Gerät und verlässt es nicht",
