      'rl.d6b': "Knoten-Datenbank",
      'rl.d6c': "Bloße Summen ohne Personenbezug — nur „wie viele“",
      'rl.a1': "Der Äther ist ein offener Chat. Alles, was du schreibst, sieht jeder, der den Knoten öffnet — Suchmaschinen eingeschlossen.",
      'rl.a2': "Wenn du unter 14 bist, schreib hier nur mit Wissen deiner Eltern.",
      'rl.a3': "Paket und Seite sind das Hobbyprojekt einer einzelnen Person. Es entsteht abends und kann ohne Vorwarnung offline sein.",
      'rl.rNote': "Die Aufsicht kann eine Nachricht löschen und einen Überlebenden für einen Tag stummschalten. Jede solche Handlung landet in einem Protokoll, das jeder lesen kann.",
