      'pr.since': "Auf Sendung seit {d}",
      'pr.kicker': "// Personalakte · Station Buran",
      'pr.loadT': "Hole die Akte aus dem Archiv…",
      'pr.loadB': "Die Station sucht den Eintrag zum Rufzeichen.",
      'pr.noneT': "Akte nicht gefunden",
      'pr.noneB': "Unter «{n}» ist auf der Station niemand verzeichnet. Vielleicht war dieser Überlebende noch nie auf Sendung.",
      'pr.noNickT': "Kein Rufzeichen angegeben",
