      'ae.h1': '<span class="ice">ÄTHER</span>',
      'ae.heroDesc': 'Ein Kommunikationsterminal für Überlebende. Hier läuft ein Live-Chat-Signal, das Forum „Lagerfeuer" glimmt, und die beschädigte KI der Station antwortet. Der Äther ist instabil — aber er existiert.',
