      'ae.aiSub': '// BORD-KI · INTEGRITÄT 41%',
      'ae.chip1': 'wie stellt man Messing her', 'ae.chip2': 'wo finde ich Kupfer', 'ae.chip3': 'wie bleibe ich warm', 'ae.chip4': 'das Spiel stürzt ab', 'ae.chip5': 'wer bist du',
      'ae.aiInputPh': 'Anfrage an das Stationssystem…', 'ae.aiSendBtn': 'Anfrage',
      'ae.aiGreeting': '…<span class="ai-tag" style="display:inline">[SYSTEM ERWACHT]</span> Ich bin FROST-01, die Bord-KI der Station Buran. Integrität 41%. Womit kann ich helfen, Überlebender? Du kannst unten einen Vorschlag antippen.',
