      'rl.kicker': "// Статут вузла · станцыя Буран",
      'rl.title': "Як тут прынята",
      'rl.lead': "Эфір трымаецца на некалькіх простых дамоўленасцях. Іх няшмат, і яны не пра фармальнасці — а пра тое, каб сюды хацелася вяртацца.",
      'rl.h1': "Правілы эфіру",
      'rl.h2': "Што станцыя пра цябе захоўвае",
      'rl.h3': "Узрост і адказнасць",
      'rl.r1': "<b>Паважай выжыўцаў.</b> Абразы, цкаванне і пагрозы — прамы шлях да заглушэння. Спрачацца пра шэйдары можна, пераходзіць на чалавека — не.",
      'rl.r2': "<b>Ніякай рэкламы і спаму.</b> Спасылкі на свае праекты дарэчныя ў адказ на пытанне, а не ў кожным паведамленні.",
      'rl.r3': "<b>Не выкладвай чужыя даныя.</b> Сапраўдныя імёны, адрасы, перапіскі, скрыншоты асабістых паведамленняў — не сюды.",
      'rl.r4': "<b>Трымай узроставую планку.</b> Эфір чытаюць падлеткі: без парнаграфіі, жорсткасці дзеля жорсткасці і прапаганды наркотыкаў.",
      'rl.r5': "<b>Спасылкі — на старонкі, а не на файлы.</b> Простыя спасылкі на архівы і выканальныя файлы выдаляюцца: праверыць іх змест станцыя не можа.",
      'rl.r6': "<b>Адзін голас — адзін выжывец.</b> Накрутка галасоў, другія акаўнты дзеля апвоўтаў і падробка чужога пазыўнога спыняюцца.",
      'rl.r7': "<b>Скардзься, а не ваюй.</b> Кнопка «паскардзіцца» пад паведамленнем працуе і даходзіць да наглядчыка. Узаемная лаянка — не.",
      'rl.d1a': "Пазыўны, статус, клас, фракцыя",
