      'rl.d5a': "Схаваныя выжыўцы, налады сігналаў, прагрэс Кодэкса",
      'rl.d5b': "Толькі твой браўзер",
      'rl.d5c': "Гэта асабістая справа прылады і на вузел не едзе",
      'rl.d6a': "Лічыльнікі праглядаў і сцягванняў",
      'rl.d6b': "База вузла",
      'rl.d6c': "Агульныя лікі без прывязкі да людзей — проста «колькі ўсяго»",
      'rl.a1': "Эфір — адкрыты чат. Усё, што ты пішаш, бачна любому, хто зойдзе на вузел, уключна з пошукавымі сістэмамі.",
      'rl.a2': "Калі табе менш за 14 гадоў, пішы сюды толькі з ведама бацькоў.",
      'rl.a3': "Зборка і сайт — аматарскі праект аднаго чалавека. Ён робіцца вечарамі і можа быць недаступным без папярэджання.",
      'rl.rNote': "Наглядчык можа выдаліць паведамленне і заглушыць выжыўца на суткі. Усе такія дзеянні трапляюць у журнал, адкрыты для чытання любому.",
      'rl.dLead': "Коратка: толькі тое, што патрэбна эфіру, каб працаваць. Ні рэкламы, ні аналітыкі, ні продажу даных — тут проста няма ні таго, ні другога.",
      'rl.tWhat': "Што",
