      'rl.dNote': "Выгрузіць усё, што станцыя пра цябе ведае, і сцерці асобу можна ў профілі Эфіру — раздзел «Твае даныя». Сказанае ў эфір застанецца: выдаляць чужыя запісы вузел не ўмее, і абяцаць адваротнае было б няпраўдай.",
