      'f.kicker': '// Што ўнутры', 'f.title': 'Ключавыя асаблівасці',
      'f.sub': '{n} слупоў, на якіх трымаецца выжыванне ў Astral RPG.',
      'feat.winter.t': "Вечная зіма", 'feat.winter.d': "Тэмпература цела, абмаражэнне і гіпатэрмія. Холад ва ўсіх біёмах забівае хутчэй за зомбі. Патрэбныя вогнішчы, уцепленае адзенне і цяпло — інакш смерць ад марозу за хвіліны.",
      'feat.infected.t': "Узмоцненыя заражаныя", 'feat.infected.d': "Дзясяткі тыпаў: хуткія бегуны, браняваныя, выбуховыя, начныя паляўнічыя. Орды (The Hordes) накочваюцца хвалямі ноччу. Укус заражае — без лекаў інфекцыя прагрэсуе.",
      'feat.guns.t': "Рэалістычная агнястрэльная зброя", 'feat.guns.d': "TACZ і 4 пакі зброі: аддача, перазарадка, прыцэлы, абвесы, заклінванне. Ад пісталетаў да штурмавых вінтовак — патроны на вагу золата, кожны стрэл на рахунку.",
      'feat.create.t': "Глыбокая тэхніка Create", 'feat.create.d': "30+ аддонаў Create: канвееры, цягнікі, генератары, аўтаматычная вытворчасць патронаў, вялікія гарматы для абароны і нават ядзерная энергія для позняй гульні.",
      'feat.medicine.t': "Медыцына па частках цела", 'feat.medicine.d': "First Aid: пашкоджанне канечнасцяў, пераломы, крывацёкі, шыны і бінты. Cure: сістэма заражэння з лячэннем. Здароўе — гэта не адна паласа, а стан кожнай часткі цела.",
      'feat.food.t': "Псаванне і голад", 'feat.food.d': "Ежа гніе без кансервацыі (Diet/Spoiled). Аднастайны рацыён насычае горш — патрэбна разнастайнасць. Харчаванне ператвараецца ў тактычную задачу доўгага выжывання.",
      'feat.defense.t': "Абарона базы", 'feat.defense.d': "SecurityCraft: камеры, кодавыя замкі, міны, сігналізацыі, лазеры. Illager Invasion: варожыя NPC штурмуюць сховішча. База — гэта крэпасць, якую трэба абараняць.",
      'feat.world.t': "Мёртвы свет", 'feat.world.d': "Tectonic генеруе ледзяныя пікі і тундру. Пакінутыя гарады, бункеры, вайсковыя базы, барыкады. Immersive Weathering састарыў свет — усё выглядае даўно пакінутым.",
      'feat.shaders.t': "Эксклюзіўныя шэйдары", 'feat.shaders.d': "Кастомны прэсет на базе Complementary + EuphoriaPatches: халодная колеракарэкцыя, аб'ёмны туман, ззяючы снег. 5 профіляў — ад Potato да Extreme пад любое жалеза.",
