      'dlp.h1': 'Пратакол <span class="ice">разгортання</span>',
      'dlp.sub': 'Пяць крокаў ад пустога лаўнчара да першага ўдыху ў мёртвым свеце. Ідзі за пратаколам — і зборка запусціцца з першага разу.',
      'dlp.rail1': 'Сканаванне', 'dlp.rail2': 'Тэрмінал', 'dlp.rail3': 'Спампоўка', 'dlp.rail4': 'Памяць', 'dlp.rail5': 'Актывацыя',
