      'rl.home': "Станцияға",
      'rl.toAether': "Эфирге",
      'rl.kicker': "// Түйін жарғысы · Буран станциясы",
      'rl.title': "Мұнда қалай қабылданған",
      'rl.lead': "Эфир бірнеше қарапайым келісімге сүйенеді. Олар көп емес әрі формальділік туралы емес — мұнда қайта оралғың келуі үшін.",
      'rl.h1': "Эфир ережелері",
      'rl.h2': "Станция сен туралы нені сақтайды",
      'rl.h3': "Жас және жауапкершілік",
      'rl.r1': "<b>Тірі қалғандарды сыйла.</b> Балағаттау, қудалау және қорқыту — үнсіз қылуға тікелей жол. Шейдер туралы таласуға болады, адамға көшуге болмайды.",
      'rl.r2': "<b>Жарнама мен спам жоқ.</b> Өз жобаларыңа сілтеме сұраққа жауап ретінде орынды, әр хабарда емес.",
      'rl.r3': "<b>Бөтен деректерді жариялама.</b> Нақты аттар, мекенжайлар, хат алмасулар, жеке хабар скриншоттары — бұл жерге емес.",
      'rl.r4': "<b>Жас шегін сақта.</b> Эфирді жасөспірімдер оқиды: порнография, қатыгездік үшін қатыгездік және есірткі насихаты жоқ.",
      'rl.r5': "<b>Сілтеме — бетке, файлға емес.</b> Мұрағаттар мен орындалатын файлдарға тікелей сілтемелер жойылады: станция олардың ішін тексере алмайды.",
      'rl.r6': "<b>Бір дауыс — бір тірі қалған.</b> Дауыс жинау, апвоут үшін екінші аккаунт және бөтен позывнойды қолдан жасау тоқтатылады.",
      'rl.r7': "<b>Шағымдан, соғыспа.</b> Хабардың астындағы «шағымдану» түймесі жұмыс істейді және күзетшіге жетеді. Өзара ұрыс жетпейді.",
      'rl.d1a': "Позывной, мәртебе, класс, фракция",
      'rl.d1b': "Түйін базасы + сенің браузерің",
      'rl.d1c': "Эфирде және жеке істе сені тану үшін",
      'rl.d2a': "Анонимді нөмір (uid)",
      'rl.d2b': "Түйін базасы",
      'rl.d2c': "Бір тірі қалғанды екіншісінен ажыратады. Онда есім де, пошта да жоқ",
      'rl.d3a': "Хабарлар, идеялар, сызбалар, қаза жазбалары",
      'rl.d3b': "Түйін базасы, оқуға ашық",
      'rl.d3c': "Бұл — эфирдің өзі: жазылғанның бәрін бәрі көреді",
      'rl.d4a': "Аман қалу күні және рекорд",
      'rl.d4b': "Түйін базасы + сенің браузерің",
      'rl.d4c': "Куәліктегі атақ және жеке істегі жол",
      'rl.d5a': "Жасырылғандар, сигнал баптаулары, Кодекс прогресі",
      'rl.d5b': "Тек сенің браузерің",
      'rl.d5c': "Бұл құрылғының жеке ісі, түйінге кетпейді",
      'rl.d6a': "Қаралым және жүктеу санауыштары",
      'rl.d6b': "Түйін базасы",
      'rl.d6c': "Адамға байланысы жоқ жалпы сандар — жай «қанша»",
      'rl.a1': "Эфир — ашық чат. Жазғаныңның бәрін түйінге кірген кез келген адам, соның ішінде іздеу жүйелері көреді.",
      'rl.a2': "Егер 14-ке толмаған болсаң, мұнда тек ата-анаңның хабарымен жаз.",
      'rl.a3': "Жинақ пен сайт — бір адамның әуесқой жобасы. Ол кештерде жасалады және ескертусіз қолжетімсіз болуы мүмкін.",
      'rl.rNote': "Күзетші хабарды жойып, тірі қалғанды бір тәулікке үнсіз қыла алады. Мұндай әрекеттің бәрі кез келген адам оқи алатын журналға түседі.",
      'rl.dLead': "Қысқаша: тек эфирдің жұмысына керегі. Жарнама да, аналитика да, дерек сатуы да жоқ.",
