      'cdx.lead': "Жинақтың ашылу реті: не неден кейін келеді және не немен бөгелген. Өткеніңді белгіле — түйін қай жерде тоқтағаныңды есінде сақтайды. Shift + карточкаға басу оған дейінгі жолды көрсетеді.",
