      'cdx.logs.name': "Ағаш пен жылу",
      'cdx.logs.desc': "Кітаптың бірінші қадамы: кез келген ағаштың 16 бөренесі. Одан от та, қабырға да шығады. Осы сәттен бастап температура көрсеткішін бақыла.",
      'cdx.campfire.name': "Алау",
      'cdx.campfire.desc': "Алғашқы жылу көзі, шамамен +10°. Жылыну үшін қасына тұр. Таңға қарай сөнеді — ол бір түнге ғана есептелген.",
      'cdx.campfire.recipe': "бөрене мен ағаш көмірінен жасалған кәдімгі алау",
