      'about.body': 'Astral RPG — мұзға айналған ядролық соғыстан кейінгі әлемде тіршілік ету туралы хардкор жинақ. Суық зомбиден жылдам өлтіреді. Тағам шіриді. Отын алтындай қымбат. Әр шешім — «тәуекелге бару» мен «қараңғыда қату» арасында. Мұнда жеңіл жеңіс жоқ, тек тағы бір күн үшін төлейтін баға бар.',
