      'tch.forumCta': '📡 Көмектеспеді ме? «Эфир» форумынан сұра',
      'tch.r1t': 'Жедел жад жетіспеуі',
      'tch.r1b': 'Ойынға бөлінген жад жетпеді. «ЖЖЖ калькуляторы» қойындысын аш — ойынға 6–10 ГБ бөл және дайын Java аргументтерін қой. Егер жад бар-жоғы 8 ГБ болса — іске қосар алдында браузер мен фондық бағдарламаларды жап.',
      'tch.r2t': 'Mixin қатесі (модтар қақтығысы)',
      'tch.r2b': 'Модтардың бірі өз өзгерістерін енгізе алмады — бұл дерлік әрқашан екі модтың қақтығысы немесе үйлесімсіз нұсқа. Жинаққа қолмен қосылған модтарды алып таста. Мәселелі миксиннің аты логта көрсетілген.',
      'tch.r3t': 'Тәуелділік жетіспейді',
      'tch.r3b': 'Қандай да бір модқа кітапхана-тәуелділік жетпейді. Жинақ толық орнатылмаған немесе қажетті кітапхана-мод жойылған. Оны толық қайта орнат, сыртқы көзқараста «артық» көрінетін модтарды жоймай — олардың көбі кітапханалар.',
      'tch.r4t': 'Модтардың қайталанғаны',
      'tch.r4b': 'mods қалтасында бір модтың екі нұсқасы жатыр. <code>mods</code> қалтасын ашып, ескі көшірмесін жой — әр модтың бір ғана нұсқасы қалуы керек.',
      'tch.r5t': 'Java нұсқасы қате',
      'tch.r5b': 'Жинаққа басқа Java нұсқасы керек. 1.20.1 үшін бұл — <code>Java 17 (64-bit)</code>. Лаунчерде Java 17 таңда. Java 8 немесе 21-де көптеген модтар іске қосылмайды.',
      'tch.r6t': 'Модтар нұсқаларының сәйкессіздігі',
      'tch.r6b': 'Модтардың нұсқалары бір-бірімен немесе лоадермен сәйкес келмейді. Барлық модтардың бір Minecraft және Forge/Fabric нұсқасына арналғанына және жинақ басқа нұсқадағы модтармен араласпағанына көз жеткіз.',
      'tch.r7t': 'Табиғи құлау (драйвер / темір)',
      'tch.r7b': 'Ойын табиғи деңгейде құлады — көбіне бұл видеокарта драйвері. Драйверлерді жаңарт (GeForce/Adrenalin), дискретті видеокартада іске қос. OptiFine + шейдерлер бар болса — оларсыз байқап көр.',
      'tch.r8t': 'OpenGL / видеодрайвер мәселесі',
      'tch.r8b': 'Терезе ашу кезіндегі графика ақауы. Видеокарта драйверлерін жаңарт, ойынның кірістірілген емес, дискретті картаны қолданатынына көз жеткіз. Ескі карталарда OpenGL 4.x қолдауы жетіспеуі мүмкін.',
      'tch.r9t': 'OptiFine анықталды',
      'tch.r9b': 'OptiFine Forge 1.20.1-дегі модтармен жиі қақтығысады. Егер құлау рендермен байланысты болса — OptiFine-ды жойып, оның орнына Rubidium/Embeddium + Oculus қолдан.',
      'tch.r10t': 'Рендер ескертулері (Create / шейдерлер)',
      'tch.r10b': 'Create + шейдерлер байланысының белгілі критикалық емес ескертулері. Тұрақтылыққа әсер етпейді. FPS түскенде шейдер профилін төмендет немесе Create баптауларында Flywheel backend-ті өшір.',
      'tch.r11t': 'Әлемді өңдеу кезіндегі құлау (ticking)',
      'tch.r11b': 'Ойын мән, блок немесе әлемді өңдеу кезінде құлады — әдетте нақты мод кінәлі (жоғарыдағы «кінәліні» қара). Егер құлау әлемге кіргенде қайталанса — әлем мәселелі объектінің маңында бүлінген болуы мүмкін.',
      'tch.r12t': 'Тізілім қатесі / мазмұн жоғалды',
      'tch.r12b': 'Әлемнен жойылған немесе жаңартылған модтың блогы/заты/мобы жоғалды. Бар болып тұрған әлемде модтарды жоймаңыз және жаңартпаңыз. Жойылған модты қайтар немесе жаңа әлем баста.',
      'tch.r13t': 'Мод конфигурациясының қатесі',
      'tch.r13b': 'Мод конфигурациясы бүлінген немесе қате өңделген. <code>config</code> қалтасынан мәселелі файлды жой — мод оны әдепкі баптаулармен қайта жасайды.',
      'tch.r14t': 'Желілік қате (критикалық емес)',
      'tch.r14b': 'Мод іске қосылу кезінде желіден жаңартуды тексере алмады. Ойынға әсер етпейді — бұл жай ғана байланыс күту уақыты аяқталуы.',
      'tch.r15t': 'Әлем / сақтау бүлінуі',
      'tch.r15b': 'Әлем файлы бүлінген немесе қол жеткізу қақтығысы бар. saves қалтасының сақтық көшірмесін жаса. SessionLock — ойын басқа терезеде іске қосылған дегенді білдіреді; артық Minecraft процестерін жап.',
      'tch.footerTitle': 'Техникалық бөлім · Astral RPG',
